import { l, type Class8Chapter } from './types';
import type { L, ChoiceTask, SelectTask, MatchTask, OrderTask, TaskBase } from './types';

const option = (id: string, label: L, feedback: L) => ({ id, label, feedback });
const base = (prompt: L, context: L, success: L, correction: L, hint: L): TaskBase => ({ prompt, context, success, correction, hint });
const choose = (b: TaskBase, options: ChoiceTask['options'], correct: string): ChoiceTask => ({ ...b, kind: 'choice', options, correct });
const select = (b: TaskBase, items: SelectTask['items'], expected: string[], presentation: SelectTask['presentation'] = 'cards'): SelectTask => ({ ...b, kind: 'select', items, expected, presentation });
const match = (b: TaskBase, rows: MatchTask['rows'], options: MatchTask['options'], presentation: MatchTask['presentation'] = 'match', simulation?: MatchTask['simulation']): MatchTask => ({ ...b, kind: 'match', rows, options, presentation, ...(simulation ? { simulation } : {}) });
const effect = (label: L, rowId: string, allowedAnswers: string[], allowed: L, denied: L) => ({ label, checks: [{ rowId, allowedAnswers }], allowed, denied });
const order = (b: TaskBase, items: OrderTask['items'], expected: string[]): OrderTask => ({ ...b, kind: 'order', items, expected });
const scene = (title: L, caption: L, dialogue: L) => ({ title, caption, dialogue });
const row = (id: string, label: L, answer: string, explanation: L) => ({ id, label, answer, explanation });
const meta = (slug: string, title: L, summary: L, topics: [L, L, L], outcomes: [L, L, L], familyAction: L, reflection: L, teacherPrompt: L): Pick<Class8Chapter, 'slug' | 'title' | 'strand' | 'summary' | 'topics' | 'outcomes' | 'familyAction' | 'reflection' | 'teacherPrompt' | 'rubric'> => ({
  slug, title, strand: 'Cybersecurity', summary, topics, outcomes, familyAction, reflection, teacherPrompt,
  rubric: [l('Identify the relevant evidence and explain its connection to the purpose.', 'ज़रूरी सबूत पहचानें और बताएँ कि वह काम के उद्देश्य से कैसे जुड़ा है।'), l('Demonstrate a complete plan with the supplied simulation and record its checks.', 'दिए गए सिमुलेशन में पूरा प्लान दिखाएँ और उसकी जाँच दर्ज करें।'), l('Revise the plan for the changed case and explain one remaining limitation.', 'बदले हुए मामले के लिए प्लान सुधारें और उसकी एक सीमा समझाएँ।')],
});

